(window.webpackJsonp=window.webpackJsonp||[]).push([[108],{548:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、《约翰福音》14:12节预言说“我所做的事，信我的人也要做。”耶稣所说的，是信他的人，也会效法他做事的方式。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、他始终以上帝的心来洞察他遭遇的每一个处境，并由此使自己的心随神的心意而动。他主动地将这样的内心感动付诸行动，去服侍他人。在这服侍当中，他走近他、与他同在。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、当你也是这样，以上帝的心洞察处境，而不是隔岸观火当看客;以主动的心付诸行动，而不是守株待兔等求助;以同在的心服侍他人，而不是居高临下做施主，你就是在效法主耶稣。《约翰福音》14:12节的预言也就通过你得到了应验上。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家平安。今天我们继续来讲路加福音7:11~17节。我们一起来读。我们今天讲道的题目是:“主的预言，你来应验”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在今天的经文中，路加记载了耶稣在拿因城门外复活一个寡妇的儿子的神迹。拿因城位于加利利地区的南部，靠近撒玛利亚。第11节告诉我们，当时与耶稣同行的，不仅有他的门徒，还有极多的人群。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在讲解6章11至16节的经文时我们曾提到，此前关于安息日的争论中，耶稣实际上否定了当时犹太宗教人士对安息日律法的解释，更是在整体上否定了他们解释旧约律法的方法。这也就从根本上否定了当时犹太教的权威。因此，那些宗教领袖就认定这位来自拿撒勒的、弥赛亚运动的带领者是“异端”，并且开始商议要怎样除掉他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("以拣选十二使徒为标志，主耶稣的事工从此进入了一个新的阶段——就是培养门徒。这样，在他离世归父之后，门徒便能继续承担他在地上所开始的使命。因此，从那时起，训练门徒就成了耶稣事工的核心目标之一。他藉着教导传递真理，藉着亲身示范树立榜样，也藉着一次次差遣，让门徒在实践之中受操练、得成长。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天的这段经文同样如此。所以，接下来我将和大家一起观察:主耶稣当时做了什么、他为身边的门徒留下了怎样的榜样，并在此基础上一起思考——如今我们作为主耶稣的门徒，应当如何效法他的样式。我今天将给大家带来三个信息:第一，以上帝的心洞察处境;第二，以主动的心付诸行动;第三，以同在的心服侍他人。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、以上帝的心洞察处境")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们接着看第12节：“就在他们将近城门的时候，遇见一队出殡的人。”路加特别说明，那死去的人是他母亲的独生子，而他母亲又是个寡妇。从这样的描述中，我们可以感受到这位妇人生命中接连遭受的重击:她先是失去了丈夫，成了一个寡妇;如今，她仅有的、赖以倚靠的儿子也离开了她。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们都知道，在古代社会，无论是在以色列还是其他地区，男性通常都是一个家庭的主要劳动力与经济支柱。因此，一位妇人失去丈夫，往往就意味着她失去了生活的保障和稳定的依靠。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果还有成年的子女，特别是儿子，那么她的境况还不至于陷入绝境，因为子女能够承担起家庭的生计，成为她生活的倚靠。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("然而，对那些失去丈夫又没有子女，或子女尚且年幼的寡妇来说，生活就格外艰难了。这样的人往往坠入社会的底层，用今天的话来说，就是“弱势群体”。经济基础决定着社会地位，人类社会古今中外，其实都是如此。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在我们今天所读的这段经文中，这位寡妇正是遭遇了这样双重的不幸。经文第14节记载，主耶稣称她的儿子为“少年人”，这个词在原文中正是“青年”的意思，说明这个儿子已经成年，正是他母亲唯一的倚靠与盼望。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们无从得知这个女人的丈夫是什么时候离世的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也许那已是多年前的事，那么她必定熬过了一段极其艰难的日子，独自将孩子抚养长大，日日盼望他成人，能成为这个家的支柱。如今，这一天终于到来，但唯一的支柱却骤然倒塌了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("又或许她的丈夫才离世不久，而如今连独生的儿子也失去了。就在转眼之间，她生命中所有的依靠都被夺去。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("无论是哪种情况，失去至亲的哀恸、失去倚靠的无助、对未来生活的茫然，都必然深深淹没了这位妇人的心，使她悲痛欲绝。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而路加福音7:13节说，“主看见那寡妇”。主看见的是什么?他看见的是一个在出殡队伍中被悲伤所压倒而失声哭泣的女人，他看见的是一个失去了亲人、失去了依靠、失去了希望的神的子民，他看见的是一个处在社会底层、软弱无助的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加说:“主看见那寡妇，就怜悯她，对她说:‘不要哭!’”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我想请大家首先回忆，你是否遇到过类似的场景?你是否曾经在家乡或者在某次旅途中，看到过一支出殡的队伍?")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来请大家再回忆，你当时所看见的，和主在这拿因城门看见的，有没有不同?")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你是仅仅看见了一个场景,一群人的活动,一场仪式,甚至一场热闹，亦或像主一样，看见了在这场景中，人的悲凉、无助与愁苦?或者我们更直白一点，面对一个处境，你仅仅是站在一边的看客，亦或你的心把你带入这个处境中去，以至于你也参与其中?")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我刚才只是以一支出殡的队伍为例。举一反三，我们也可思考自己如何“看”其他的处境。当你在街上遭遇到一场吵架斗殴，你看见了什么?当你从新闻上阅读到以色列轰炸巴勒斯坦，你看见了什么?当你的某个朋友结婚，你看见了什么?当你某个朋友离婚，你看见了什么?当你某个亲人身染重病，你看见了什么?当你的老板为他生意成功而庆祝，你看见了什么?")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这取决于你以怎样的心来看。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("王国维在《人间词话》中提到过一种写诗的意境，叫“有我之境”:“以我观物，故物皆著我之色彩”。也就是说，你以怎样的心来看事物、看处境，你所看到的就会体现你的心境。你以不同的心境看，看到的也会不同;而你所看到的又会反过来影响你的心，所以你产生的感受也会不同。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("杜甫《春望》中有一句话，很好地体现了这样的过程:“感时花溅泪，恨别鸟惊心”。诗人因时局动荡、与亲人离别而伤感忧闷，看到花，花也在掉泪;听到鸟，鸟也在悲鸣。这样去看花、听鸟，又会反过来影响他的心，增添他的伤感。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这虽然是中国古人的一种“观物”的文学理论，却与我们今天这段经文中，主在面对出殡队伍时的反应有相通之处。从经文中我们知道，主并非以看客之心来观看这个处境，从而视这个女人的状况与己无关。如果是这样，这个处境对他心的影响将可能不过是满足了好奇。大家想想自己存着看客、看热闹的心时，是不是这样?无论你是突然遇到一支出殡队伍、或者一场街边的吵架斗殴，又或是其他不寻常的景象。你看见了，但这个场景给你带来的影响，往往只是好奇心得到满足。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但主不是这样的。他是以另一种心来看，所以他虽然也看，却看见了不同;而他所看见的又反过来影响他的心，第13节说，这影响就是他动了“怜悯”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么他是以怎样的心来看这场景呢?在《约翰福音》5:30，耶稣说:“我不求自己的意思，只求那差我来者的意思。”6:38也说:“因为我从天上降下来，不是要按自己的意思行，乃是要按那差我来者的意思行。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("很显然，耶稣无时无刻不以神的心意看待周围的事物。而神不会以看客、看热闹的心来看待孤苦无助的人。在旧约中，神一次又一次要求他的子民善待寡妇。我自己数了一下，仅在《申命记》中，提到要照顾、善待“孤儿”、“寡妇”、“寄居的”这些弱势群体的经文，就有十一处之多。在诗篇、箴言、先知书中也多次提醒以色列人不可欺压寡妇、孤儿。从这些经文我们就可以看到，神不会为“孤儿”、“寡妇”、“寄居的”等等这些社会弱势群体的状态而欢喜或无动于衷，而是难过、不忍，所以会要求他的子民们去扶助他们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这样我们就知道,当神看见这个寡妇,他的心会是悲伤、难过、不忍的。而主耶稣以这样的心来看这出殡的场景，他看见的就是这个在出殡队伍中那个被悲伤压倒、失声哭泣的女人，那个失去了亲人、失去了依靠、失去了希望的神的子民，那个处在社会底层、软弱无助的人。他所看见的这一切，又反过来影响他的心，于是主耶稣，“就怜悯她”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这就是今天我们要从主耶稣身上学习的第一点，我们要以上帝的心去看、去洞察我们周围每一个具体的处境。他关注的焦点是人。看见那些软弱、无助的人，他会难过、不忍;看见那些在罪中沉沦的人会，他会愤怒，也会忧伤;看见那些悔改归向他的人，他会欢欣、喜悦。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("只有当我们以上帝的心来洞察我们周围的处境,你所看见的才是神所看见的;而你看见的才会正确地对你的心产生影响。就像主耶稣，他以神的心去看、去洞察这出殡的处境，看见这个无助的寡妇，他就怜悯她。同样，当我们以上帝的心来洞察我们遭遇的一切处境，我们将看见不同的人，我们所看见的，就会带给我们内心不同的感动:对那些软弱、无助的，我们也会难过、不忍、怜悯;对那些在罪中沉沦的，我们也会愤怒、也为他忧伤;对那些悔改归正的，我们也会喜悦、欢欣。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、以主动的心付诸行动")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们继续看第13节后面到第15节的经文。当主动了怜悯，便对寡妇说“不要哭!”于是他停住了出殡的队伍，对死人说:“少年人，我吩咐你，起来!”使这少年从死里复活，之后把他交给他母亲。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从这几节经文我们知道，耶稣动了怜悯的心，紧接着他就使用了神给他的资源，一种称为“权柄”的东西，让这个少年活过来、并交给他的母亲。对这位母亲而言，她重新得回了他的儿子，今后的生活也重新有了保障。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这段经文中，我想首先请大家注意是，当主耶稣动了怜悯的心，他没有就停在那里。他立刻采取行动，去服侍那个他看见的人。弟兄姐妹们，真实的内心一定会体现于外在的行动。这一点，我在多次讲道都曾提及。在讲“平地宝训”的时候我说过，你真心信福音，就必然会在外在行动上表现出追求圣洁、努力去遵守神的律法。在上次讲那个百夫长的经文时我也说过，你有发自内心的热切，就一定会在为解决问题而积极想办法、采取行动。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天的经文我们也看到，主耶稣对这个寡妇动了怜悯的心，他就会开始行动起来，去服侍她。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对这段经文，我另想请大家注意的一点是:在整个过程中，这位需要帮助的寡妇是没有任何行动的。不像之前记载的神迹中的那些受惠者，她没有向主乞求帮助，也没有任何行为让我们看到他对主有什么信心。所以，是主耶稣主动向她伸出了援助之手，主动让他怜悯的内心表现于外在的行动。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这就是今天我们要从主耶稣身上学习的第二点。在第一点我们谈到，我们以上帝的心来洞察周围的处境，我们就会像神那样去看见其中的人，而我们的心就被所看见的人产生正确的影响，或怜悯不忍，或愤怒忧伤，或欢欣喜悦。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而接下来，就需要我们以一颗主动的心，将这样的内心感动付诸行动、体现在我们对人的服侍当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当看见有软弱无助的，我们会对他们怜悯不忍，这样的心就应促使我们“主动”去使用神给我们的资源去服侍他们，包括为他们的需要祷告、也包括向他们提供实际物质和属灵上的帮助;")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当看见那沉迷罪中的，我们会对他们愤怒忧伤，这样的心也应促使我们“主动”去使用神给我们的资源去服侍他们，包括在祷告中把自己公义的怒火交托给神并祈求神赦免他们，也包括劝诫其悔改、归信，甚至还可以包括为了他们的益处，施以适当管教;")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当看到那悔改归正的，我们会对他们欢欣喜悦，这心仍应促使我们“主动”去使用神给我们的资源去服侍他们，包括在祷告中为他们感谢神、包括接纳他们、包括继续陪伴他们在属灵上不断成长。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("上一次我通过那位百夫长的经文，向大家讲解了一个大信心之人，要以乞丐般的勇敢、行动中的热切来向主恳求。那是我们面对主、面对神的时候应该如何。而今天的经文与此不同，主耶稣是在向他的门徒们示范面对人的时候应该怎么做。面对人，我们不是等待人来向我们恳求才行动，而是应该像主对这个寡妇所做的，主动采取行动，把你的心体现在对她的服侍当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而在面对人时主动采取行动，这是主耶稣的作为，也正是神的作为。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对犯罪的亚当，神主动寻找、呼唤他(创世记3:9)，并赐下拯救的应许(创世记3:15);")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对事奉偶像的他拉一家(约书亚记24:2)，神主动呼召他的儿子亚伯兰(创世记12:1)，并与他立约(创世记15)。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对悖逆的以色列，神宣告了对他们的审判，也借众先知的口承诺，他必主动再施拯救。何西阿说“神必追讨以色列素来给诸巴力烧香的罪，但后来也必劝导以色列，领她到旷野，对她说安慰的话书2:13~14)。耶利米先知也宣告，神“在怒气、愤怒和大忿怒中，将以色列人赶到各国，日后他必从那里将他们招聚出来，领他们回到此地，使他们安然居住。”(耶利米书32:32)")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在新约当中，这启示就更清楚了。《约翰福音》6:44说:“若不是差我来的父吸引人，就没有能到我这里来的。”《哥林多前书》12:3说:“若不是被圣灵感动的，也没有能说‘耶稣是主’的。” 《罗马书》5:6说:“我们还软弱的时候，基督就按所定的日期为罪人死。”《约翰一书》里也说:“不是我们爱神，乃是神爱我们，差他的儿子为我们的罪做了挽回祭”(约一4:10)、“我们爱，是因为神先爱我们。”(约一4:19)")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这些经文都让我们看到，神不是被动等待的，他是主动作为的;神的心意不止于他的意念之中，也体现在他的行动之上。那么我们这些属基督的人、属神的人，理应效法基督、效法神，以一颗主动的心，将我们对人的负担付诸具体的行动,以神给我们的资源,去服侍那个我们看见的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、以同在的心服侍他人")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好。下面请大家再来看第14节，这里有一个细节描述。主耶稣“进前按着杠，抬的人就站住了”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当时犹太人出殡时用来将死者的遗体运往安葬地点的，不是我们现在所用的封闭棺材，而是一种类似于担架的抬床，死者的遗体放在床上面，周围的人都能看到他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("根据当时犹太人对《民数记》19:11-16关于触摸尸体的律法的解释，任何人触摸了尸体或与尸体接近的物品，都会在七天内于礼仪上不洁净。这个人需要按规定履行一定的仪式，才会在第七天晚上重归洁净。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("按照这个解释，主耶稣伸手按杠的行为，就会导致他在礼仪上不洁净。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这其实不是第一次了。在路加福音第5章，也有过类似的事。我们一起翻到那里来看一看。在5:12~13节，记载了主耶稣风病人的神迹。这麻风病人来求他医治说:“主若肯，必能叫我洁净了。”然后耶稣伸手摸他，说:“我肯，你洁净了吧!”大麻风立刻就离了他的身。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，根据当时犹太人对摩西律法的解释，触摸麻风病人，也会导致自己在礼仪上变得不洁净。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当然，神学家们一般认为主在这两个事件中的触摸行为，并不会导致他在礼仪上不洁净。但为何如此的神学解释，我今天不想多谈。我希望大家关注的是，主耶稣的这“多此一举”以及由此我们可以学到什么？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么我说他是“多此一举”呢?上次关于百夫长的经文我们已经讲了，主耶稣医治的能力，并非来自于专业技能，而是源于他的权柄。对于有权柄的人，要的不是他的行动，而是他的决定。有决定就够了，不需要他亲自去操作。在那个百夫长眼中，耶稣就是这样一位有权柄的主。所以他求耶稣不必劳动亲往，只要说一句话，表达他的决定就可以了。只要有这个决定，那么世间的一切都会迅速行动起来，贯彻执行。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，在路加福音第5章中，主也是凭着他的权柄医治这位麻风病人。所以他一说“我肯，你洁净了吧!”大麻风立刻就离了他的身。在我们今天的经文中，主也是凭着他的权柄复活这个年轻人。所以他一说“少年人，我吩咐你，起来!”那死人就坐起，并且说话。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("既然如此，他完全可以站在那里，只说这么一句话就好。为什么他要多此一举，去摸这个麻风病人?为什么他要多此一举，去按这个杠?")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来体会一下他这“多此一举”，对于这些被他服侍的人而言，会有什么不同。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不难想象，这个麻风病人在当时犹太社会的生存状态。他长期被隔绝于人群之外，每个见到他的人都害怕他、躲避他。但在主这里，他却被主接近、被主触摸。主凭他的权柄医治他，也亲自去抚摸他的伤痛。这时候，这麻风病人所得到的不仅是生理上的医治，他还有一个认识:这个有权柄、有怜悯、帮助我、服侍我的人，他不是疏离的、不是高高在上的、而是与我同在的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对今天经文中的这位寡妇也是如此。很显然，当时她顾可不会顾及什么礼仪上是否洁净。她一定是一手抓住她独生儿子的手，一手掩面痛哭，只希望这队伍走得慢一点，再慢一点。而主耶稣呢，他不是站在远处、心生怜悯、口出命令，而是走入这个送葬队伍中，去靠近这寡妇、去触摸她的伤痛。同样，在这时候，这位寡妇不仅是得回了她的儿子，她也有一个认识:这位有权柄、有怜悯、帮助我、服侍我的人，他不是疏离的、不是高高在上的、而是与我同在的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这种“同在感”非常重要。因为它会给心灵带来温暖、带来慰藉，它会在人与人之间产生情感联系，也会产生更多的信任。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在1996年，耶鲁大学的历史学家佩里坎(Jaroslav Pelikan)出版了一本名为《玛利亚的世纪流变》(Mary Through the Centuries)的书。他通过对历史资料的分析，向人们展示了为什么天主教中会形成将玛利亚视为中保、向玛利亚祷告的传统。他发现，随着耶稣在中世纪日益被理解为遥远而超越的存在，玛利亚的角色也相应增强。当人们越发畏惧基督严厉的权威，玛利亚就成为了一个更容易亲近的对象。从这里我们也可以理解到这种“同在感”对人的重要性。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这就是今天我们要从主耶稣身上学习的第三点:在你主动去服侍他人的过程中，你要与你服侍的人“同在”。我说的这同在，不一定是指物理上的在一起、靠近，而更多的是一种也就是你要在心上去靠近他们、去与他们一起，而不是疏离的、高高在上的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我在讲平地宝训的时候曾提到，我们是神的儿女、是有君尊的祭司、是宇宙中的贵族，因此我们是高贵的;我也曾提到，我们承认自己一无所有、一无所能，需要完全依靠主，那神的国就是我们的，因此我们又是富有的。但这尊贵和富有，不意味着我们是高高在疏离的;神的儿女会有神的心，而与人同在的，正是神。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正是有这“同在”的心，神用人类能懂的语言启示他自己;")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正是有这“同在”的心，神亲手用皮子做衣，遮盖亚当夫妇的赤身露体(创世记3:21);")])],1),t._v(" "),v("p",[t._v("正是有这“同在”的心，神在旷野用云柱和火柱引导以色列人(尼希米记9:19);")]),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正是有这“同在”的心，神管教、鞭打他所收纳的每一个儿子(希伯来书12:6);")])],1),t._v(" "),v("p",[t._v("正是有这“同在”的心，主不以自己与神同等为强夺的，反倒虚己，取了奴仆的样式，道成了肉身住在我们中间(腓立比书2:7);")]),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正是有这“同在”的心，主伸出他的手去触摸那个被人厌恶的麻风病人;")])],1),t._v(" "),v("p",[t._v("正是有这“同在”的心，主径直走入那悲伤的送葬队伍;")]),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正是有这“同在”的心，圣灵亲自住在我们身体里面，引导我们(罗马书8:14)，并用说不出的叹息为我们祷告(罗马书8:26)。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("或许你可以把这样的心理解为是“迁就”或者“俯就”，但我更喜欢用“同在”这个词，因为它强调了“我是和你在一起的”这意思在里面，而这层意思所体现的，是我们对人的牵挂、善意、接纳、鼓励、期盼。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我想,世间好父母的养育之心,或许最能帮助我们具象化地理解“同在”二字。好父母是怎样待孩子的呢?他们不仅供应物质的需用，更给予亲密的陪伴与拥抱;他们俯就自己，用孩子能懂的话语耐心沟通;他们不只下达指令，更挽起袖子与孩子一同行动;当孩子犯错，他们不只是指出对错，更鼓励悔改;当孩子深陷罪恶，他们满心忧虑、牵肠挂肚，切切期盼他回转;而当浪子回头的一刻，他们张开双臂全然接纳，并欢喜快乐地一同庆祝。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是“同在”。它不是高高在上，不是冷漠疏离，不是筑墙自守;而是走进其中，俯就、同行、触摸;是共情、牵挂、扶持，是接纳、鼓励、期盼。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我很难去描述当你有一颗“同在”的心，你会表现出什么样子来。但我十分确定，神是最好的榜样。刚才我们说到“好父母”，但这个世界上，哪有父母比我们在天上的父更完美呢?他贵为宇宙的至高者，却又与他的儿女同在。他至为圣洁，却不嫌弃我们的肮脏鄙陋，他接近我们、引导我们、陪伴我们、触摸我们、训练我们、管教我们、安慰我们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们越去默想神的作为、去思想他如何父母般地、朋友般地对待我们，我们就越能知道何为“同在”，我们也就越能以“同在”的心去主动服侍我们所看见的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以当保罗有了这“同在”的心，他向律法以下的人，就做律法以下的人;向没有律法的人，就做没有律法的人;向软弱的人，就做软弱的人(罗马书9:20~22);他虽然远在以弗所，仍为哥林多教会忧愁(哥林多后书2:1);他要求哥林多教会逐出那淫乱而不悔改的人，把他的肉体交给撒旦，但同时又让他们切切期盼这人的“灵魂在主耶稣的日子可以得救”(哥林多前书5:5)。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也只有有了这“同在”的心，神的儿女们才不会站在一个高高在上的、疏离的、法官的位置上去论断人，而会处于一个低低在下的、仆人的位置上去服侍人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，主耶稣在《约翰福音》14:12节预言说“我实实在在地告诉你们:我所做的事，信我的人也要做，并且要做比这更大的事，因为我往父那里去。”显然，他并不是在说我们也会重复去做他做过的那些事本身，因为我们各人的际遇与他不同，神给我们的恩赐也与他不同。他会遇到一个有麻风病的人来求他，你不会;他会遇见一个仆人生病的百夫长，你不会;他会在拿因城门口遇到一个失去独生子的寡妇，你不会;神给了他医病、使死人复活的权柄，没有给你这同样的恩赐。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣所说的，是信他的人，也会效法他做事的方式。当他去到父那里，圣灵就降下来，住在每个信徒的心中，赐予我们不同的恩赐，把我们带入不同的处境。这时候，按着这方式做事的人，就不再是他一人，而是一群人;这种做事方式所彰显的神的荣耀，就不局限于主耶稣一人一地一时，而是随着我们的脚踪延伸到普天之下、光照于历代之间。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天我们讲解的，就是主耶稣做事的方式。他始终以上帝的心来洞察他遭遇的每一个处境，他把关注的焦点放在人上，并由此使自己的心随神的心意而动。他主动地将这样的内心感动付诸行动，使用神给与他的资源、恩赐去服侍他人。在这服侍当中，他不因自己是在施予恩典而高高在上，也不嫌对方的鄙陋而与之疏离，而是走近他、与他同在。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当你也是这样，以上帝的心洞察处境，而不是隔岸观火当看客;以主动的心付诸行动，而不是守株待兔等求助;以同在的心服侍他人，而不是居高临下做施主，你就是在效法主耶稣，你就是按照他做事的方式在做事。主耶稣的这句预言也就通过你得到了应验上--“我所做的事，信我的人也要做，并且要做比这更大的事”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我想问的是，主的这句预言，你应验得怎么样？")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);